"""Blender export: produces a native .blend by driving a local Blender install
in background mode; without Blender it writes a .glb plus a one-click import
script the user can run from Blender's Scripting tab."""
from __future__ import annotations

import glob
import os
import shutil
import subprocess

_blender_path: str | None = None

SCRIPT = r'''
# Generated by N64 Asset Studio - imports the exported models into Blender.
# Run with:  blender --background --python this_script.py
# or open it in Blender's "Scripting" tab and press "Run Script".
import bpy, os
HERE = {folder!r}
if not os.path.isdir(HERE):
    HERE = os.path.dirname(os.path.abspath(__file__))
MODELS = {models!r}
OUT = {out!r}
SCALE = {scale!r}

bpy.ops.wm.read_factory_settings(use_empty=True)
for i, rel in enumerate(MODELS):
    path = os.path.join(HERE, rel)
    before = set(bpy.data.objects)
    bpy.ops.import_scene.gltf(filepath=path)
    new = [o for o in bpy.data.objects if o not in before]
    name = os.path.splitext(os.path.basename(rel))[0]
    coll = bpy.data.collections.new(name)
    bpy.context.scene.collection.children.link(coll)
    for o in new:
        for c in list(o.users_collection):
            c.objects.unlink(o)
        coll.objects.link(o)
        if o.parent is None:
            o.scale = (SCALE, SCALE, SCALE)
for img in bpy.data.images:
    # images from .glb files are already packed; pack anything else so the
    # .blend is self-contained
    if img.packed_file is None and img.filepath:
        try:
            img.pack()
        except Exception:
            pass
if OUT:
    bpy.ops.wm.save_as_mainfile(filepath=os.path.join(HERE, OUT))
    print("Saved", OUT)
'''


def set_blender_path(p: str | None) -> None:
    global _blender_path
    _blender_path = p or None


def find_blender() -> str | None:
    if _blender_path and os.path.isfile(_blender_path):
        return _blender_path
    exe = shutil.which("blender")
    if exe:
        return exe
    patterns = []
    for env in ("ProgramFiles", "ProgramFiles(x86)", "LOCALAPPDATA"):
        root = os.environ.get(env)
        if root:
            patterns += [os.path.join(root, "Blender Foundation", "Blender*", "blender.exe"),
                         os.path.join(root, "Steam", "steamapps", "common", "Blender", "blender.exe")]
    patterns += [r"C:\Program Files\Blender Foundation\Blender*\blender.exe",
                 r"C:\Program Files (x86)\Steam\steamapps\common\Blender\blender.exe",
                 "/Applications/Blender.app/Contents/MacOS/Blender", "/usr/bin/blender",
                 "/snap/bin/blender"]
    hits = []
    for p in patterns:
        hits += glob.glob(p)
    return sorted(hits)[-1] if hits else None


def export_blender(meshes, folder: str, blend_name: str, scale: float = 1.0) -> dict:
    """Write each mesh as .glb, a Blender import script and (if Blender is
    installed) a .blend file containing all of them."""
    from .models import export_glb, safe

    os.makedirs(folder, exist_ok=True)
    rels = []
    for mesh in meshes:
        fn = safe(mesh.name) + ".glb"
        export_glb(mesh, os.path.join(folder, fn), scale)
        rels.append(fn)
    blend = safe(blend_name) + ".blend"
    script_path = os.path.join(folder, safe(blend_name) + "_import_into_blender.py")
    with open(script_path, "w", encoding="utf-8") as f:
        f.write(SCRIPT.format(folder=os.path.abspath(folder), models=rels, out=blend, scale=1.0))
    result = {"glb": [os.path.join(folder, r) for r in rels], "script": script_path, "blend": None,
              "message": ""}
    exe = find_blender()
    if not exe:
        result["message"] = ("Blender was not found, so the .blend could not be built automatically. "
                             f"Open Blender > Scripting, load '{os.path.basename(script_path)}' and press "
                             "Run Script (or set the Blender path in Settings and export again).")
        return result
    try:
        flags = 0x08000000 if os.name == "nt" else 0
        subprocess.run([exe, "--background", "--factory-startup", "--python", script_path],
                       check=True, timeout=900, cwd=folder, creationflags=flags,
                       stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
        out = os.path.join(folder, blend)
        if os.path.isfile(out):
            result["blend"] = out
            result["message"] = f"Created {blend} with Blender ({exe})."
        else:
            result["message"] = "Blender ran but did not produce a .blend file."
    except (subprocess.SubprocessError, OSError) as e:
        result["message"] = f"Blender failed: {e}"
    return result
